/*
 * square_mail
 *
 * An n by m sheet of interlocking square links that prints in place: each
 * link sits as close to its neighbours as leaves `clearance` mm between
 * them (see square_mail_spacing()).
 */
module square_mail(link_loop_rad, link_circle_rad, loop_skew, cut_offset, n, m, clearance = 0.4)
{
    space = square_mail_spacing(link_loop_rad, link_circle_rad, loop_skew, cut_offset, clearance);

    for (i = [0:n - 1])
    {
        for (j = [0:m - 1])
        {
            translate([ i * space, j * space, 0 ]) square_link(link_loop_rad = link_loop_rad, link_circle_rad = link_circle_rad,
                                                               loop_skew = loop_skew, cut_offset = cut_offset);
        }
    }
}

use <../lib/fit.scad>;

/* [Part] */
// Select which part to render for STL export. "Both" is preview only:
// export the parts separately.
part_to_render = "Both"; // [Plate, Pins, Both]

/* [Dimensions] */
plate_w = 120;
plate_d = 30;
plate_t = 6;
strip_d = 16;
strip_t = 3;
pin_dia = 4;
pin_h = 6;
spacing = 18;
clearances = [-0.2, 0.0, 0.1, 0.2, 0.3, 0.4];

// Rows, measured from the plate/strip center line.
pin_row_y = -plate_d / 4;
hole_row_y = plate_d / 4;

// X position of station i, centered on the plate.
function station_x(i) = (i - (len(clearances) - 1) / 2) * spacing;

assert(len(clearances) > 0, "clearances must not be empty");
assert(spacing > pin_dia + 2, "spacing must leave material between stations");
assert(plate_w > len(clearances) * spacing, "plate_w must fit all stations");
assert(pin_h > 0 && plate_t > 0 && strip_t > 0, "thicknesses must be positive");

module hole_plate() {
  union() {
    difference() {
      cube([plate_w, plate_d, plate_t], center = true);
      for (i = [0 : len(clearances) - 1])
        translate([station_x(i), hole_row_y, -1])
          cylinder(h = plate_t + 2,
                   r = hole_radius(pin_dia, clearances[i]), $fn = 64);
    }
    // Clearance labels, raised on the top face between the rows.
    // They stand 0.6 mm above the plate: the original code extruded
    // 0.8 mm from 0.2 mm below the top face (see lib/labels.scad).
    for (i = [0 : len(clearances) - 1])
      translate([station_x(i), 0, plate_t / 2 - label_overlap()])
        emboss_label(clearances[i], 3.5, 0.6);
  }
}

module pin_strip() {
  union() {
    cube([plate_w, strip_d, strip_t], center = true);
    for (i = [0 : len(clearances) - 1])
      translate([station_x(i), 0, strip_t / 2])
        cylinder(h = pin_h, r = pin_dia / 2, $fn = 64);
    // Clearance labels, raised on the top face below the pins.
    // They stand 0.6 mm above the strip, as on the plate.
    for (i = [0 : len(clearances) - 1])
      translate([station_x(i), -strip_d / 2 + 2.5, strip_t / 2 - label_overlap()])
        emboss_label(clearances[i], 3, 0.6);
  }
}

if (part_to_render == "Plate") {
  hole_plate();
} else if (part_to_render == "Pins") {
  pin_strip();
} else if (part_to_render == "Both") {
  // Preview both, side by side.
  hole_plate();
  translate([0, plate_d / 2 + strip_d / 2 + 6, 0])
    pin_strip();
} else {
